package com.argument.segmentationtrial;
import com.argument.common.exception.*;
import com.argument.version.*;
import com.argument.version.port.*;
import com.argument.version.port.VersionIdentity.Actor;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.argument.adjudication.AdjudicationService.require;

@Service @Profile("(local | test) & !prod")
public class SegmentationTrialService {
 private final com.argument.membera.service.SegmentationService independent;private final SegmentationTrialRepository store;private final AnnotationDependencies data;private final VersionRepository versions;private final VersionService access;private final SegmentationAgreement algorithm;private final ObjectMapper mapper;
 public SegmentationTrialService(SegmentationTrialRepository store,AnnotationDependencies data,VersionRepository versions,VersionService access,SegmentationAgreement algorithm,ObjectMapper mapper,com.argument.membera.service.SegmentationService independent){this.independent=independent;this.store=store;this.data=data;this.versions=versions;this.access=access;this.algorithm=algorithm;this.mapper=mapper;}
 private void arbiter(Actor a,String c){require(a.permission("ADJUDICATION_WORK")&&access.hasAssignment(a,c,"ARBITER"),ErrorCode.FORBIDDEN,"仅本案例负责裁定者可计算和确认切割");}
 private ObjectNode writable(String c){VersionJson.uuid(c);versions.lockCase(c);var doc=data.lock("taskDocument",c);var task=data.lock("task",doc.path("taskId").asText());return doc;}
 private void mutable(ObjectNode doc){require("IN_PROGRESS".equals(data.read("task",doc.path("taskId").asText()).path("status").asText())&&"ANNOTATING".equals(doc.path("status").asText()),ErrorCode.LOCKED_RESOURCE,"切割输入仅在案例标注阶段开放");}
 private ObjectNode base(Actor a,ObjectNode doc){var n=mapper.createObjectNode();VersionJson.stamp(n,a.id(),VersionJson.now());for(String f:List.of("documentTextVersionId","annotationScopeId"))n.set(f,doc.get(f));n.set("taskDocumentId",doc.get("id"));n.put("textSha256",data.read("text",doc.path("documentTextVersionId").asText()).path("contentSha256").asText());return n;}
 private void baseline(ObjectNode n,ObjectNode doc){for(String f:List.of("documentTextVersionId","annotationScopeId"))require(n.path(f).equals(doc.path(f)),ErrorCode.CONFLICT,"切割来源基准已变化");require(n.path("textSha256").equals(data.read("text",doc.path("documentTextVersionId").asText()).path("contentSha256")),ErrorCode.CONFLICT,"切割来源原文已变化");}
 public Set<Integer> boundaries(ObjectNode doc,JsonNode rows){var scope=data.read("scope",doc.path("annotationScopeId").asText());var textVersion=data.read("text",doc.path("documentTextVersionId").asText());String text=textVersion.path("normalizedText").asText();int left=scope.path("startOffset").asInt(-1),right=scope.path("endOffset").asInt(-1);require(scope.path("documentTextVersionId").equals(doc.path("documentTextVersionId"))&&"CONFIRMED".equals(scope.path("status").asText())&&VersionJson.sha256(text).equals(textVersion.path("contentSha256").asText())&&left>=0&&left<right&&right<=text.length(),ErrorCode.VALIDATION_ERROR,"文本或范围基准无效");require(rows.isArray()&&!rows.isEmpty()&&rows.size()<=10000,ErrorCode.VALIDATION_ERROR,"切割需为 1–10000 个连续 UTF-16 区间");int next=left;var internal=new TreeSet<Integer>();for(var row:rows){require(row.isObject()&&row.size()==2&&row.path("startOffset").isIntegralNumber()&&row.path("startOffset").canConvertToInt()&&row.path("endOffset").isIntegralNumber()&&row.path("endOffset").canConvertToInt(),ErrorCode.VALIDATION_ERROR,"切割区间仅允许整数 startOffset/endOffset");int start=row.path("startOffset").asInt(),end=row.path("endOffset").asInt();require(start==next&&end>start&&end<=right&&validBoundary(text,start)&&validBoundary(text,end),ErrorCode.VALIDATION_ERROR,"切割有遗漏、重叠或切开 UTF-16 代理对");if(end<right)internal.add(end);next=end;}require(next==right,ErrorCode.VALIDATION_ERROR,"切割未覆盖完整范围");return internal;}
 private boolean validBoundary(String text,int at){return at==0||at==text.length()||!Character.isLowSurrogate(text.charAt(at))||!Character.isHighSurrogate(text.charAt(at-1));}
 @Transactional public ObjectNode submit(Actor actor,String c,String key,ObjectNode body){VersionJson.uuid(key);var doc=writable(c);require(actor.permission("ANNOTATION_WORK")&&access.hasAssignment(actor,c,"ANNOTATOR"),ErrorCode.FORBIDDEN,"仅本案例独立标注员可提交本人切割");var cached=versions.receipt(actor.id(),"TRIAL-SUBMIT:"+c,key,VersionJson.canonicalHash(body));if(cached!=null)return cached;mutable(doc);require(data.find("segmentationSubmission","taskDocumentId",c).isEmpty(),ErrorCode.CONFLICT,"该案例已使用独立切割审核流程，请通过 S01 提交");boundaries(doc,body.path("boundaries"));var n=base(actor,doc);n.set("boundaries",body.path("boundaries").deepCopy());n.put("submittedById",actor.id()).put("attemptNumber",store.list("SUBMISSION",c).stream().filter(v->actor.id().equals(v.path("submittedById").asText())).mapToInt(v->v.path("attemptNumber").asInt()).max().orElse(0)+1);store.append("SUBMISSION",n);receipt(actor,"TRIAL-SUBMIT:"+c,key,body,n);return n;}
 private List<ObjectNode> inputs(String c){if(!data.find("segmentationSubmission","taskDocumentId",c).isEmpty())return independent.acceptedInputs(c);var latest=new TreeMap<String,ObjectNode>();for(var n:store.list("SUBMISSION",c)){String actor=n.path("submittedById").asText();if(!latest.containsKey(actor)||latest.get(actor).path("attemptNumber").asInt()<n.path("attemptNumber").asInt())latest.put(actor,n);}var valid=new ArrayList<ObjectNode>();for(var n:latest.values()){String actor=n.path("submittedById").asText();boolean assigned=data.find("assignment","taskDocumentId",c).stream().anyMatch(a->{if(!actor.equals(a.path("userId").asText())||!"ACTIVE".equals(a.path("status").asText())||!"ANNOTATOR".equals(a.path("assignmentRole").asText()))return false;var m=data.read("member",a.path("taskMemberId").asText());return "ACTIVE".equals(m.path("status").asText())&&"ANNOTATOR".equals(m.path("memberRole").asText())&&m.path("userId").equals(a.path("userId"))&&m.path("taskId").equals(data.read("taskDocument",c).path("taskId"));});if(assigned)valid.add(n);}return valid;}
 @Transactional public ObjectNode calculate(Actor actor,String c,String key,ObjectNode body){VersionJson.uuid(key);var doc=writable(c);arbiter(actor,c);var cached=versions.receipt(actor.id(),"TRIAL-CALCULATE:"+c,key,VersionJson.canonicalHash(body));if(cached!=null)return cached;mutable(doc);var submissions=inputs(c);require(submissions.size()>=Math.max(2,doc.path("requiredAnnotators").asInt()),ErrorCode.INSUFFICIENT_VERSIONS,"尚未收齐 N 名不同标注员当前有效切割");var sets=new ArrayList<Set<Integer>>();for(var s:submissions){baseline(s,doc);sets.add(boundaries(doc,s.path("boundaries")));}var result=algorithm.calculate(sets);var n=base(actor,doc);n.put("algorithmCode",algorithm.code()).put("algorithmVersion",algorithm.version()).put("threshold",0.8).put("thresholdOperator",">").put("aggregateScore",result.score()).put("passed",result.passed()).put("scoreNumerator",result.numerator()).put("scoreDenominator",result.denominator()).put("computedAt",VersionJson.now());var ids=n.putArray("inputSubmissionIds");submissions.forEach(s->ids.add(s.path("id").asText()));var pairs=n.putArray("perPairScores");for(var pair:result.pairs()){var p=pairs.addObject();p.put("leftSubmissionId",submissions.get(pair.left()).path("id").asText()).put("rightSubmissionId",submissions.get(pair.right()).path("id").asText()).put("common",pair.common()).put("leftCount",pair.leftCount()).put("rightCount",pair.rightCount()).put("score",pair.score());}n.put("inputDigest",VersionJson.sha256(submissions.toString()));store.append("CALCULATION",n);receipt(actor,"TRIAL-CALCULATE:"+c,key,body,n);return n;}
 @Transactional public ObjectNode confirm(Actor actor,String c,String key,ObjectNode body){VersionJson.uuid(key);var doc=writable(c);arbiter(actor,c);var cached=versions.receipt(actor.id(),"TRIAL-CONFIRM:"+c,key,VersionJson.canonicalHash(body));if(cached!=null)return cached;mutable(doc);if(!data.find("segmentationSubmission","taskDocumentId",c).isEmpty())require(data.find("checkpoint","taskDocumentId",c).stream().noneMatch(cp->"CONFIRMED".equals(cp.path("status").asText())),ErrorCode.LOCKED_RESOURCE,"本轮统一关口已确认，不能再次生成关口");var calculation=store.get("CALCULATION",VersionJson.uuid(body.path("calculationId").asText()));require(c.equals(calculation.path("taskDocumentId").asText()),ErrorCode.FORBIDDEN,"计算不属于本案例");baseline(calculation,doc);require(calculation.path("passed").asBoolean(),ErrorCode.LOCKED_RESOURCE,"一致性必须严格大于 0.8");require(calculation.path("inputDigest").asText().equals(VersionJson.sha256(inputs(c).toString())),ErrorCode.CONFLICT,"独立提交或成员分配已变化，请重新计算");String reason=body.path("reason").asText();require(!reason.isBlank()&&reason.length()<=2000,ErrorCode.VALIDATION_ERROR,"请填写 1–2000 字确认理由");boundaries(doc,body.path("unifiedBoundaries"));var existing=store.list("CHECKPOINT",c).stream().filter(n->n.path("calculationId").equals(calculation.path("id"))).toList();require(existing.isEmpty(),ErrorCode.CONFLICT,"该计算已有确认关口，请读取原记录");var n=base(actor,doc);n.set("calculationId",calculation.get("id"));n.set("sourceSubmissionIds",calculation.path("inputSubmissionIds").deepCopy());n.set("agreementScore",calculation.get("aggregateScore"));n.put("requiredThreshold",0.8).put("status","CONFIRMED").put("reason",reason).put("confirmedById",actor.id()).put("confirmedAt",VersionJson.now());n.set("unifiedBoundaries",body.path("unifiedBoundaries").deepCopy());n.put("boundaryHash",VersionJson.sha256(n.path("unifiedBoundaries").toString()));store.append("CHECKPOINT",n);store.checkpoint(n);receipt(actor,"TRIAL-CONFIRM:"+c,key,body,n);return n;}
 @Transactional public ObjectNode bind(Actor actor,String c,String key,int expected,ObjectNode body){VersionJson.uuid(key);writable(c);String draftId=VersionJson.uuid(body.path("draftId").asText());var draft=data.lock("draft",draftId);require(c.equals(draft.path("taskDocumentId").asText())&&actor.permission("ANNOTATION_WORK")&&access.hasAssignment(actor,c,"ANNOTATOR")&&actor.id().equals(data.read("assignment",draft.path("assignmentId").asText()).path("userId").asText()),ErrorCode.FORBIDDEN,"只能绑定本人草稿");var cached=versions.receipt(actor.id(),"TRIAL-BIND:"+draftId,key,VersionJson.canonicalHash(body));if(cached!=null)return cached;mutable(data.read("taskDocument",c));require("ACTIVE".equals(draft.path("status").asText()),ErrorCode.LOCKED_RESOURCE,"草稿已锁定");require(expected==draft.path("recordVersion").asInt(),ErrorCode.CONFLICT,"草稿已变化，请刷新后重新绑定");var cp=store.get("CHECKPOINT",VersionJson.uuid(body.path("checkpointId").asText()));require(c.equals(cp.path("taskDocumentId").asText()),ErrorCode.FORBIDDEN,"关口不属于本案例");baseline(cp,data.read("taskDocument",c));draft.set("segmentationCheckpointId",cp.get("id"));com.argument.adjudication.AdjudicationService.touch(draft,actor);draft.put("revision",draft.path("revision").asInt()+1);data.replace("draft",draft);receipt(actor,"TRIAL-BIND:"+draftId,key,body,draft);return draft;}
 public ObjectNode workspace(Actor actor,String c){VersionJson.uuid(c);boolean arbiter=actor.permission("ADJUDICATION_WORK")&&access.hasAssignment(actor,c,"ARBITER");require(arbiter||actor.permission("ANNOTATION_WORK")&&access.hasAssignment(actor,c,"ANNOTATOR"),ErrorCode.FORBIDDEN,"无本案例切割权限");var n=mapper.createObjectNode().put("mode","LOCAL_TRIAL").put("teamReviewRequired",true).put("canConfirm",arbiter);var doc=data.read("taskDocument",c);n.put("canWrite","ANNOTATING".equals(doc.path("status").asText())&&"IN_PROGRESS".equals(data.read("task",doc.path("taskId").asText()).path("status").asText()));var scope=data.read("scope",doc.path("annotationScopeId").asText());n.set("scope",scope);String text=data.read("text",doc.path("documentTextVersionId").asText()).path("normalizedText").asText();n.put("scopeText",text.substring(scope.path("startOffset").asInt(),scope.path("endOffset").asInt()));var submissions=n.putArray("submissions");store.list("SUBMISSION",c).stream().filter(s->arbiter||actor.id().equals(s.path("submittedById").asText())).forEach(submissions::add);var calculations=n.putArray("calculations");if(arbiter)store.list("CALCULATION",c).forEach(calculations::add);var checkpoints=n.putArray("checkpoints");store.list("CHECKPOINT",c).forEach(checkpoints::add);return n;}
 private void receipt(Actor actor,String op,String key,ObjectNode body,ObjectNode result){versions.receipt(actor.id(),op,key,VersionJson.canonicalHash(body),result,mapper.createObjectNode(),result,body.path("reason").asText());}
}
